class TrackSymmetricTensorDegeneratePoints(Node):

    def __init__(self, parent_node_id : str, time_steps : int, backend : str):
        if correctness_checks_on():
            if not tree.has_node(parent_node_id):
                raise Exception(f"There is no node with id {parent_node_id}")
            if backend not in options_lists["tracking"]:
                raise Exception(f"Invalid tracking backend {backend}. Valid choices are {enumerate_list(options_lists['tracking'])}")
            if time_steps == 0 or time_steps < -1 or time_steps > tree.node(parent_node_id).root_node.time_steps:
                raise Exception(f"Invalid number of time steps. Must be between 1 and {tree.node(parent_node_id).root_node.time_steps} or -1 for all time steps.")

        super().__init__(parent_node_id, types.SymmetricTensorDegeneratePoints, types.SymmetricTensorDegeneratePoints, locals(), True, True)

        if time_steps == -1:
            self.time_steps = self.root_node.time_steps
        else:
            self.time_steps = time_steps
